 }

+var (
+	failureLine = regexp.MustCompile(`(?i)fail|error|panic|exception`)
+	digitRun    = regexp.MustCompile(`[0-9]+`)
+)
+
+// failingLines is the sorted set of the failure lines of a check's output: its trimmed lines that
+// mention a failure or an error and are not shell trace lines, with each run of digits replaced
+// by "#" so that counts and timings do not tell two runs apart.
+func failingLines(out string) []string {
+	seen := map[string]bool{}
+	lines := []string{}
+	for _, l := range strings.Split(out, "\n") {
+		l = strings.TrimSpace(l)
+		if strings.HasPrefix(l, "+") || !failureLine.MatchString(l) {
+			continue
+		}
+		l = digitRun.ReplaceAllString(l, "#")
+		if !seen[l] {
+			seen[l] = true
+			lines = append(lines, l)
+		}
+	}
+	sort.Strings(lines)
+	return lines
+}
